  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Why Ethics Matters: God, Truth and Conscience$j$, $j${"readings": [{"title": "Micah 6 (King James Version)", "url": "/portal/bible/Micah/6"}], "body": "Ethics is the study of right and wrong and of how people ought to live. Everyone makes ethical choices, from telling the truth to treating others fairly. Christian ethics asks, What does God require, and how do I follow Him? Micah 6:8 says, He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?\n\nChristians believe that right and wrong are not just opinions. They rest on the character of God, who is holy, just, loving and true. God has made human beings in His image (Genesis 1:27), so people have dignity and moral responsibility. God has also given us a conscience, an inner sense of right and wrong. Romans 2:15 speaks of the work of the law written in their hearts, their conscience also bearing witness. Conscience is a gift, but it can be trained well or poorly, so it must be shaped by Scripture and the Holy Spirit.\n\nSources of ethical guidance include Scripture, the Holy Spirit, the church, wise counsel, reason and experience. Scripture is the final authority.\n\nWorked example: a student sees a classmate cheat. Ask: What does God require? Who is affected? What would honesty look like? Common mistake: deciding by feelings or by what is popular. Test every choice against God's Word.\n\nYour task: (1) Define ethics and Christian ethics. (2) Explain where right and wrong come from. (3) Describe how conscience should be trained.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome to Christian Ethics. I am Dr. Alex L. Jenkins Sr., and I am glad you are here. Listen, every day you make choices that matter, and this course will help you make them with wisdom and faith.\n\nEthics is the study of right and wrong and how people ought to live. Christian ethics asks, What does God require, and how do I follow Him? Micah 6:8 says, He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?\n\nNow watch this. Right and wrong are not just opinions. They rest on the character of God, who is holy, just, loving and true. God made us in His image, so every person has dignity and moral responsibility. God also gave us a conscience, an inner sense of right and wrong. But conscience must be shaped by Scripture and the Holy Spirit.\n\nSources of guidance are Scripture, the Spirit, the church, wise counsel, reason and experience. Scripture is the final authority.\n\nDo not decide by feelings or popularity. Test every choice against God's Word.\n\nYour task is to define ethics, explain where right and wrong come from and describe how to train conscience. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Why Ethics Matters: God, Truth and Conscience$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 The Law and the Greatest Commandments$j$, $j${"readings": [{"title": "Exodus 20 (King James Version)", "url": "/portal/bible/Exodus/20"}], "body": "God gave Israel the Ten Commandments in Exodus 20. The first four teach love toward God: no other gods, no idols, respect for His name, and keeping the Sabbath. The last six teach love toward people: honor father and mother, do not murder, do not commit adultery, do not steal, do not bear false witness, and do not covet. Exodus 20:15 says, Thou shalt not steal, and Exodus 20:16 says, Thou shalt not bear false witness against thy neighbour.\n\nGod's law shows His holiness and our need for a Saviour. It also protects human life, families, property and truth. Jesus did not set the law aside. He summed it up in two commands. Matthew 22:37 and 39 says, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind. And the second is like unto it, Thou shalt love thy neighbour as thyself. Love for God and love for neighbor are the heart of all ethics.\n\nJesus also gave the Golden Rule in Matthew 7:12: all things whatsoever ye would that men should do to you, do ye even so to them. Christians keep God's commands not to earn salvation but because they love Him. Paul wrote that love is the fulfilling of the law.\n\nWorked example: stealing breaks the eighth commandment and also fails to love a neighbor. Common mistake: treating rules as a checklist without love. Obedience should come from the heart.\n\nYour task: (1) List the two groups of commandments. (2) Write the two great commandments in your own words. (3) Apply the Golden Rule to a school situation.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, God did not leave us guessing about how to live. He gave us His commandments.\n\nIn Exodus 20 the first four commandments teach love toward God: no other gods, no idols, respect for His name and keeping the Sabbath. The last six teach love toward people: honor father and mother, do not murder, do not commit adultery, do not steal, do not bear false witness, and do not covet.\n\nNow watch this. God's law shows His holiness and our need for a Saviour. It also protects life, families, property and truth. Jesus did not set the law aside. He summed it up. In Matthew 22, He said, Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind. And the second is like unto it, Thou shalt love thy neighbour as thyself.\n\nJesus also gave the Golden Rule in Matthew 7:12: all things whatsoever ye would that men should do to you, do ye even so to them.\n\nWe keep God's commands not to earn salvation, but because we love Him. Obedience should come from the heart, not from a checklist.\n\nYour task is to list the two groups of commandments, restate the great commandments and apply the Golden Rule. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 The Law and the Greatest Commandments$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Character and the Fruit of the Spirit$j$, $j${"readings": [{"title": "Galatians 5 (King James Version)", "url": "/portal/bible/Galatians/5"}], "body": "Ethics is about more than rules. It is also about character, the kind of person you become through your habits. Character is shaped by what you repeat. Small choices form habits, and habits form character. Proverbs 22:1 says that a good name is rather to be chosen than great riches. Many ethicists call good habits of character virtues and bad habits vices. Classic virtues include wisdom, courage, self control and justice.\n\nThe Bible describes the character the Holy Spirit grows in believers. Galatians 5:22 and 23 says, But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, meekness, temperance: against such there is no law. Fruit grows slowly and comes from a healthy root. We cannot produce it by willpower alone. We stay connected to Christ through prayer, Scripture, worship, fellowship and obedience. John 15:5 says, I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit.\n\nThe works of the flesh in Galatians 5:19 to 21, such as hatred, strife, jealousy and drunkenness, are the opposite. Daily choices decide which one grows.\n\nWorked example: patience grows when you wait without complaining in a long line. Common mistake: waiting for a big moment to show character. Character is built in small moments and revealed in large ones.\n\nYour task: (1) Define virtue and vice. (2) Name six fruit of the Spirit. (3) Write a habit that will grow one fruit in you.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, ethics is not only about rules. It is about the kind of person you are becoming.\n\nCharacter is shaped by what you repeat. Small choices form habits, and habits form character. Proverbs 22:1 says a good name is rather to be chosen than great riches. Good habits are called virtues, like wisdom, courage, self control and justice. Bad habits are called vices.\n\nNow watch this. The Bible tells us what character the Holy Spirit grows in believers. Galatians 5:22 and 23 says, But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, meekness, temperance: against such there is no law.\n\nFruit grows slowly from a healthy root. We cannot produce it by willpower alone. We stay connected to Christ through prayer, Scripture, worship, fellowship and obedience. John 15:5 says, I am the vine, ye are the branches.\n\nThe works of the flesh, like hatred, strife and jealousy, are the opposite. Daily choices decide which grows.\n\nCharacter is built in small moments and revealed in large ones.\n\nYour task is to define virtue and vice, name six fruit of the Spirit and write a habit that grows one. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Character and the Fruit of the Spirit$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Ways of Thinking About Right and Wrong$j$, $j${"readings": [{"title": "Romans 12 (King James Version)", "url": "/portal/bible/Romans/12"}], "body": "People use different ways to decide what is right. Learning them helps you understand others and test your own thinking. Four common approaches are these. Consequences: an action is right if it produces the best results for the most people. Strength: it looks at outcomes. Weakness: results are hard to predict, and a bad act might seem justified for a good end. Duty or rules: some acts are right or wrong regardless of results. Strength: it protects people from being used. Weakness: rules can conflict. Virtue: ask what a good person would do. Strength: it focuses on character. Weakness: people disagree on what is good. Relativism: right and wrong depend on a person or culture. Strength: it respects differences. Weakness: it cannot say that any act, such as cruelty, is truly wrong.\n\nChristians draw from several of these. The Bible gives commands (duty), forms virtues (character) and calls us to care about outcomes for others. Yet it places them under the authority of God. Romans 12:2 says, And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.\n\nWorked example: should you lie to protect a friend from embarrassment? A consequences view might say yes. A duty view says no. A Christian looks to Ephesians 4:25 and speaks truth in love. Common mistake: using only one method. Test choices with Scripture, character and care for others.\n\nYour task: (1) Define the four approaches. (2) Name one strength and one weakness of each. (3) Explain why Christians place Scripture first.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, people use different ways to decide what is right, and understanding them helps you think clearly and respond with respect.\n\nHere are four. Consequences says an act is right if it brings the best results. Duty says some acts are right or wrong no matter the result. Virtue asks what a good person would do. Relativism says right and wrong depend on a person or a culture.\n\nNow watch this. Each has a strength and a weakness. Consequences focuses on outcomes, but results are hard to predict. Duty protects people from being used, but rules can conflict. Virtue shapes character, but people disagree about what is good. Relativism respects differences, but it cannot say that cruelty is truly wrong.\n\nChristians draw from several of these. The Bible gives commands, forms virtues and calls us to care about others. But it places all of them under God's authority. Romans 12:2 says, Be not conformed to this world: but be ye transformed by the renewing of your mind.\n\nTest choices with Scripture, character and care for others.\n\nYour task is to define the four approaches, give a strength and weakness of each and explain why Scripture comes first. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Ways of Thinking About Right and Wrong$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Foundations of Biblical Ethics$j$, $j${"prompt": "Write a report of at least 250 words on the foundations of Christian ethics. Use complete sentences and label each part. Micah 6:8 says, He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?\n\nPart 1: Define ethics and explain why Christians believe right and wrong rest on the character of God.\nPart 2: Explain the role of conscience and how it is trained.\nPart 3: Summarize the Ten Commandments in two groups and explain the two great commandments.\nPart 4: Define virtue and describe three fruit of the Spirit with an example of each.\nPart 5: Compare two ways of thinking about right and wrong and explain why Christians place Scripture first.", "rubric": "100 points. Part 1: 20 points. Part 2: 15 points. Part 3: 25 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Foundations of Biblical Ethics$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Walking Humbly$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes one ethical choice students face at school, (2) explains what the Golden Rule would say about it, (3) names a virtue or fruit of the Spirit that would help, and (4) connects your answer to Micah 6:8 or Matthew 22:37 to 39. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it not enough to follow your feelings when deciding right and wrong? Keep your tone kind and avoid naming real people."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Walking Humbly$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Why Ethics Matters: God, Truth and Conscience$j$, $j${"questions": [{"q": "Ethics is the study of:", "options": ["Right and wrong and how people ought to live", "Old maps", "Numbers", "Weather"]}, {"q": "Christian ethics rests on:", "options": ["Personal feelings only", "The character and Word of God", "Whatever is legal", "Popular opinion"]}, {"q": "Conscience should be:", "options": ["Ignored", "Trained by Scripture and the Holy Spirit", "Followed without question", "Silenced"]}, {"q": "Micah 6:8 says to do justly, love mercy and:", "options": ["Avoid people", "Win arguments", "Seek power", "Walk humbly with thy God"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Why Ethics Matters: God, Truth and Conscience$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,3}'::int[], array[$j$Ethics asks how we ought to live.$j$,$j$God's character and Word are the foundation.$j$,$j$A trained conscience guides well.$j$,$j$Humility before God completes the verse.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Why Ethics Matters: God, Truth and Conscience$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: The Law and the Greatest Commandments$j$, $j${"questions": [{"q": "The first four commandments focus on love toward:", "options": ["God", "Animals", "Governments", "Neighbors"]}, {"q": "Jesus summed up the law as love for God and:", "options": ["Love for neighbor", "Love for money", "Love for rules", "Love for success"]}, {"q": "The Golden Rule is found in:", "options": ["Genesis 1:1", "Psalm 23:1", "Acts 2:1", "Matthew 7:12"]}, {"q": "Christians keep God's commands because they:", "options": ["Love Him", "Want praise", "Fear being caught only", "Want to earn salvation"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: The Law and the Greatest Commandments$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,3,0}'::int[], array[$j$They teach love and honor toward God.$j$,$j$Matthew 22 gives the two great commandments.$j$,$j$Jesus taught it in the Sermon on the Mount.$j$,$j$Obedience flows from love.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: The Law and the Greatest Commandments$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Character and the Fruit of the Spirit$j$, $j${"questions": [{"q": "A virtue is:", "options": ["A bad habit", "A punishment", "A good habit of character", "A law"]}, {"q": "Galatians 5 lists the fruit of:", "options": ["The world", "Money", "Fame", "The Spirit"]}, {"q": "We grow spiritual fruit by:", "options": ["Willpower alone", "Avoiding people", "Staying connected to Christ", "Waiting for luck"]}, {"q": "Character is mostly built in:", "options": ["Small repeated choices", "Sleep", "One big event", "Birthdays"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Character and the Fruit of the Spirit$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,0}'::int[], array[$j$Virtues are good character habits.$j$,$j$The Holy Spirit grows these qualities.$j$,$j$John 15 teaches that we abide in the vine.$j$,$j$Habits form character.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Character and the Fruit of the Spirit$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Ways of Thinking About Right and Wrong$j$, $j${"questions": [{"q": "Relativism says right and wrong:", "options": ["Come from God only", "Depend on a person or culture", "Are always obvious", "Never matter"]}, {"q": "A weakness of focusing only on consequences is that:", "options": ["Results are hard to predict", "It uses Scripture", "It ignores all results", "It is too strict"]}, {"q": "A virtue approach asks:", "options": ["What is cheap?", "What is legal?", "What is popular?", "What would a good person do?"]}, {"q": "Christians place all ways of thinking under:", "options": ["Personal comfort", "Tradition alone", "The authority of God and Scripture", "Public opinion"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Ways of Thinking About Right and Wrong$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,3,2}'::int[], array[$j$Relativism denies a universal standard.$j$,$j$Outcomes are uncertain.$j$,$j$It focuses on character.$j$,$j$Scripture is the final authority.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Ways of Thinking About Right and Wrong$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Foundations of Biblical Ethics$j$, $j${"questions": [{"q": "Christian ethics asks first:", "options": ["What does God require?", "What is easiest?", "What is cheapest?", "What is popular?"]}, {"q": "God made people in His image, so people have:", "options": ["No choices", "Dignity and moral responsibility", "No value", "Only rights"]}, {"q": "Conscience is:", "options": ["Always perfect", "An inner sense of right and wrong that needs training", "A rule book", "Unimportant"]}, {"q": "The last six commandments teach love toward:", "options": ["Planets", "Animals only", "Idols", "People"]}, {"q": "Jesus said the second great commandment is to love your neighbor:", "options": ["Never", "Only friends", "As thyself", "More than God"]}, {"q": "The fruit of the Spirit includes:", "options": ["Envy", "Greed", "Love, joy and peace", "Anger and strife"]}, {"q": "A habit of good character is called a:", "options": ["Virtue", "Rule", "Vice", "Crime"]}, {"q": "Relativism cannot say that cruelty is:", "options": ["Truly wrong for everyone", "Sometimes painful", "Often discussed", "A modern idea"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Foundations of Biblical Ethics$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,3,2,2,0,0}'::int[], array[$j$God's will is the starting point.$j$,$j$Genesis 1:27 teaches human dignity.$j$,$j$It must be shaped by Scripture.$j$,$j$They guide how we treat others.$j$,$j$Matthew 22:39 says as thyself.$j$,$j$Galatians 5 lists love, joy and peace.$j$,$j$Virtues are good habits.$j$,$j$It removes a universal standard.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Foundations of Biblical Ethics$j$ on conflict (item_id) do nothing;
